{"code": "import requests
import json

orcid_ids = [
    "0000-0003-0396-0333",  # Manuela Nagel
    "0000-0002-2605-6569",  # Tatjana Gavrilenko
    "0000-0001-6102-7846",  # John Bamberg
    "0000-0002-0209-2784",  # David Ellis
    "0000-0002-1053-2030",  # Peter Giovannini
]

names = {
    "0000-0003-0396-0333": "Manuela Nagel",
    "0000-0002-2605-6569": "Tatjana Gavrilenko",
    "0000-0001-6102-7846": "John Bamberg",
    "0000-0002-0209-2784": "David Ellis",
    "0000-0002-1053-2030": "Peter Giovannini",
}

results = {}

for orcid in orcid_ids:
    url = f"https://pub.orcid.org/v3.0/{orcid}/works"
    headers = {"Accept": "application/json"}
    try:
        resp = requests.get(url, headers=headers, timeout=30)
        if resp.status_code == 200:
            data = resp.json()
            works = data.get('group', [])
            total_works = len(works)

            # Count pre-2020 works
            pre_2020 = 0
            for work in works:
                work_summaries = work.get('work-summary', [])
                for ws in work_summaries:
                    pub_date = ws.get('publication-date')
                    if pub_date and pub_date.get('year'):
                        year_val = pub_date['year'].get('value')
                        if year_val:
                            year = int(str(year_val)[:4])
                            if year < 2020:
                                pre_2020 += 1
                                break  # Count each work group only once

            results[orcid] = {
                'name': names[orcid],
                'total_works': total_works,
                'pre_2020': pre_2020
            }
            print(f"{names[orcid]}: total={total_works}, pre-2020={pre_2020}")
        else:
            print(f"{names[orcid]}: status={resp.status_code}")
    except Exception as e:
        print(f"{names[orcid]}: Error: {e}")

# Calculate average
total_pre_2020 = sum(r['pre_2020'] for r in results.values())
count = len(results)
avg = total_pre_2020 / count if count > 0 else 0
print(f"\nTotal pre-2020 works: {total_pre_2020}")
print(f"Number of researchers: {count}")
print(f"Average pre-2020 works: {avg}")"}

